import mongoose from 'mongoose';
import { OPPORTUNITY_STATUS } from '../constants/index.js';
import { jsonOptions } from './shared/json.js';
import { searchable } from './shared/searchable.js';
import { softDelete } from './shared/softDelete.js';

const { ObjectId } = mongoose.Schema.Types;

// A qualified deal with a company, moving through the stages of a pipeline.
// Created directly or by converting a lead.
const opportunitySchema = new mongoose.Schema(
  {
    // Generated by the server; never accepted from clients.
    opportunityNumber: { type: String, required: true, unique: true, immutable: true },
    name: { type: String, required: true, trim: true, maxlength: 200 },
    companyId: { type: ObjectId, ref: 'Company', required: true, index: true },
    contactId: { type: ObjectId, ref: 'Contact', index: true },
    // The lead this opportunity came from. One opportunity per lead.
    leadId: { type: ObjectId, ref: 'Lead', index: true },
    pipelineId: { type: ObjectId, ref: 'Pipeline', required: true, index: true },
    stageId: { type: ObjectId, ref: 'PipelineStage', required: true, index: true },
    sourceId: { type: ObjectId, ref: 'LeadSource' },
    estimatedValue: { type: Number, min: 0 },
    // Percent. Taken from the stage on entering it; may then be adjusted by hand.
    probability: { type: Number, min: 0, max: 100 },
    expectedCloseDate: { type: Date },
    assignedTo: { type: ObjectId, ref: 'User', index: true },
    // From the administrator-managed priority list shared with leads.
    priorityId: { type: ObjectId, ref: 'LeadPriority', index: true },
    organizationId: { type: ObjectId, ref: 'Organization' },
    // Follows the type of the current stage; never set directly.
    status: {
      type: String,
      enum: Object.values(OPPORTUNITY_STATUS),
      default: OPPORTUNITY_STATUS.OPEN,
      index: true,
    },
    // When it entered a won or lost stage.
    closedAt: { type: Date },
    notes: { type: String, trim: true, maxlength: 5000 },
    createdBy: { type: ObjectId, ref: 'User' },
  },
  {
    timestamps: true,
    toJSON: jsonOptions({
      omit: ['deletedAt'],
      aliases: {
        companyId: 'company',
        contactId: 'contact',
        leadId: 'lead',
        pipelineId: 'pipeline',
        stageId: 'stage',
        sourceId: 'source',
        priorityId: 'priority',
        organizationId: 'organization',
        assignedTo: 'assignedToUser',
        createdBy: 'createdByUser',
      },
    }),
  }
);

softDelete(opportunitySchema);

// Found by global search on these fields.
searchable(opportunitySchema, ['opportunityNumber', 'name']);

export default mongoose.model('Opportunity', opportunitySchema);
